  // ================================================================ paragraphs
  const CAPTION_LINE_RE = /^(abbildung|abb\.|bild|grafik|foto|karte|diagramm|darstellung|tabelle|tab\.|figure|fig\.|tableau|figura|tabella|illustration|chart|table|quelle|source|fonte)\s*(\d+(?:[.\-–]\d+)*[a-z]?\s*[:.)–—-]?|[:–—-])\s*\S/i;
