  // ================================================================ page analysis
  // ================================================================ formulas and footnotes
  const MATH_FONT_RE = /^(cmmi|cmsy|cmex|cmbsy|cmmib|msam|msbm|eufm|eusm|euex|rsfs|stmary|lmmi|lmsy|lmex|lmmath|latinmodern-?math|stix.*math|xits.*math|cambria-?math|asana|texgyre\w*-?math|libertinus-?math|dejavu-?math|mathjax)|math/i;
