        const bold = b.segs.every((x) => x.bold);
        const ratio = size / body;
        const first = b.segs[0].chunks.find((c) => c.text.trim()) || b.segs[0].chunks[0];
        let score = 0;
        if (ratio >= 1.4) score += 3; else if (ratio >= 1.15) score += 2; else if (ratio >= 1.05) score += 1; else if (ratio < 0.95) score -= 1.5;
        if (bold && !bodyBold) score += 1.5;
